views.feedback=['User feedback','Review ideas, problems, and reactions submitted directly by Trades users.'];const baseAdminRender=render;render=function(){baseAdminRender();renderFeedback()};function feedbackCards(items){return items.map(item=>`<article class="feedback-admin-card" data-feedback-card="${esc(item.id)}"><div class="feedback-admin-top"><div><span class="feedback-category">${esc(item.category)}</span><h3>${esc(item.title||'Untitled feedback')}</h3><p>${esc(item.company?.name||'Unknown company')} · ${esc(item.user?.fullName||item.user?.email||'Unknown user')}</p></div><span class="feedback-status ${esc(item.status)}">${esc(item.status)}</span></div><div class="feedback-message">${esc(item.message)}</div><div class="feedback-admin-meta"><span>${esc(item.user?.email||'No email')}</span><span>From ${esc(item.page||'unknown page')}</span><span>${date(item.createdAt)}</span></div><div class="feedback-admin-actions"><select data-feedback-status="${esc(item.id)}"><option value="new" ${item.status==='new'?'selected':''}>New</option><option value="reviewing" ${item.status==='reviewing'?'selected':''}>Reviewing</option><option value="planned" ${item.status==='planned'?'selected':''}>Planned</option><option value="resolved" ${item.status==='resolved'?'selected':''}>Resolved</option><option value="closed" ${item.status==='closed'?'selected':''}>Closed</option></select><textarea data-feedback-note="${esc(item.id)}" placeholder="Private owner note">${esc(item.adminNote||'')}</textarea><button class="button button-dark" type="button" data-feedback-save="${esc(item.id)}">Save</button></div></article>`).join('')||'<div class="admin-card empty-admin">No feedback matches this view.</div>'}function filteredFeedback(){const query=document.getElementById('feedbackSearch').value.toLowerCase(),status=document.getElementById('feedbackFilter').value;return adminData.feedback.filter(item=>(!status||item.status===status)&&(!query||JSON.stringify(item).toLowerCase().includes(query)))}function renderFeedback(){document.getElementById('feedbackCount').textContent=adminData.metrics.openFeedback||'';document.getElementById('feedbackGrid').innerHTML=feedbackCards(filteredFeedback())}document.getElementById('feedbackSearch').oninput=renderFeedback;document.getElementById('feedbackFilter').onchange=renderFeedback;document.getElementById('feedbackGrid').onclick=async event=>{const id=event.target.dataset.feedbackSave;if(!id)return;const button=event.target,status=document.querySelector(`[data-feedback-status="${id}"]`).value,adminNote=document.querySelector(`[data-feedback-note="${id}"]`).value;button.disabled=true;button.textContent='Saving...';try{const response=await fetch(`/api/admin/feedback/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status,adminNote})}),data=await response.json();if(!response.ok)throw Error(data.error||'Feedback could not be updated.');const index=adminData.feedback.findIndex(item=>item.id===id);adminData.feedback[index]={...adminData.feedback[index],...data.feedback};adminData.metrics.openFeedback=adminData.feedback.filter(item=>!['resolved','closed'].includes(item.status)).length;renderFeedback()}catch(error){alert(error.message)}finally{button.disabled=false;button.textContent='Save'}};
